import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 136 He told me that ...","description":"学习 would 与 had done 的回移，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 136 He told me that ...","description":"学习 would 与 had done 的回移，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 would 与 had done 的回移，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 135 The latest report","link":"/life/english/new-concept/book-1/unit-06/lesson-135"},"next":{"text":"第一册：英语初阶 · Lesson 137 A pleasant dream","link":"/life/english/new-concept/book-1/unit-06/lesson-137"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 135 The latest report","link":"/life/english/new-concept/book-1/unit-06/lesson-135"},"next":{"text":"第一册：英语初阶 · Lesson 137 A pleasant dream","link":"/life/english/new-concept/book-1/unit-06/lesson-137"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-136.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-136.md"}'),l={name:"life/english/new-concept/book-1/unit-06/lesson-136.md"};function d(i,e,s,r,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-136-he-told-me-that" tabindex="-1">第一册：英语初阶 · Lesson 136 He told me that ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-136-he-told-me-that" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 136 He told me that ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-135">配套课 Lesson 135</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>转述将来的安排和已经完成的动作 本课要掌握would 与 had done 的回移，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>latest</td><td>/ˈleɪtɪst/</td><td>adj.</td><td>最新的</td><td>the latest report</td></tr><tr><td>report</td><td>/rɪˈpɔːt/</td><td>n.</td><td>报告</td><td>a written report</td></tr><tr><td>wonder</td><td>/ˈwʌndə/</td><td>v.</td><td>想知道</td><td>wonder whether</td></tr><tr><td>tomorrow</td><td>/təˈmɒrəʊ/</td><td>adv.</td><td>明天</td><td>leave tomorrow</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>would return — 过去视角的将来</li><li>the following day — 随后一天</li></ul><h2 id="语法讲解-would-与-had-done-的回移" tabindex="-1">语法讲解：would 与 had done 的回移 <a class="header-anchor" href="#语法讲解-would-与-had-done-的回移" aria-label="Permalink to &quot;语法讲解：would 与 had done 的回移&quot;">​</a></h2><p>在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>She told me she had finished the repairs.</p></blockquote><p>她告诉我她已经修好了。</p><p>Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>would 后用 send 原形；had 后用 finished 分词，两种形式不要互换。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“She told me she had finished the repairs.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>She told me she had finished the repairs. He said he would send the document the next day.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“转述将来的安排和已经完成的动作”写两至三句，再读给同伴听。至少使用一次would 与 had done 的回移，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。 Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>按回移转述：She said, &quot;I have finished.&quot;</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She said she had finished.</p><p><strong>解析：</strong> 按本课规则判断：在常见的过去转述中，will 变 would，have/has done 变 had done。tomorrow 可根据转述时间改为 the next day，yesterday 改为 the day before。转述时间仍是同一天时不必机械替换。先明确谁在何时说话，再转换人称与时间，不能只做单词替换而让事件时间改变。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“她告诉我她已经修好了。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She told me she had finished the repairs.</p><p><strong>解析：</strong> Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：He said he would send the document the next day.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 他说他将在第二天发送文件。</p><p><strong>解析：</strong> Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：would 与 had done 的回移。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-135">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-137">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(l,[["render",d]]);export{u as __pageData,m as default};
